/* Shared master bus: pause and mute also stop tails and looping ambience. */
(function(){'use strict';let ctx,master,ambient,filter,muted=false,active=false,scene='bridge',mood='quiet',beat=0;const voices={mateo:172,vargas:112,elena:295,julian:203,marcos:139,sofia:430,sicario:151,narrador:95};
function volume(){master?.gain.setTargetAtTime(muted||!active?0:.8,ctx.currentTime,.04)}
function atmosphere(){if(!ambient)return;const outside=['bridge','school','warehouse'].includes(scene);ambient.gain.setTargetAtTime(outside?.045:.012,ctx.currentTime,.7);filter.frequency.setTargetAtTime(outside?1600:260,ctx.currentTime,.7)}
function init(){if(ctx)return;const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;ctx=new AC();master=ctx.createGain();master.connect(ctx.destination);ambient=ctx.createGain();filter=ctx.createBiquadFilter();filter.type='lowpass';const buffer=ctx.createBuffer(1,ctx.sampleRate*3,ctx.sampleRate),data=buffer.getChannelData(0);let last=0;for(let i=0;i<data.length;i++){last=(last+(Math.random()*2-1)*.08)/1.08;data[i]=last*3}const noise=ctx.createBufferSource();noise.buffer=buffer;noise.loop=true;noise.connect(filter);filter.connect(ambient);ambient.connect(master);noise.start();atmosphere();volume()}
function tone(f,d=.07,type='sine',vol=.05){if(!ctx||muted||!active)return;const t=ctx.currentTime,o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.setValueAtTime(f,t);g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(vol,t+.01);g.gain.exponentialRampToValueAtTime(.001,t+d);o.connect(g);g.connect(master);o.start(t);o.stop(t+d+.02);o.onended=()=>{o.disconnect();g.disconnect()}}
window.GameAudio={start(){init();ctx?.resume().catch(()=>{});active=true;volume()},pause(v){active=!v;volume()},mood(v){mood=v},ambience(v){scene=v;atmosphere()},toggle(){muted=!muted;volume();return muted},voice(id,index){tone((voices[id]||170)+(index%3)*12,.045,id==='sofia'?'sine':'triangle',.025)},effect(kind){switch(kind){case 'step':tone(65+Math.random()*22,.035,'triangle',.018);break;case 'paper':tone(900,.09,'sawtooth',.018);tone(640,.16,'triangle',.015);break;case 'key':tone(1400,.12,'sine',.035);tone(1900,.16,'sine',.02);break;case 'switch':tone(120,.045,'square',.025);break;case 'success':tone(330,.24,'sine',.04);tone(495,.35,'sine',.03);break;case 'shot':tone(75,.14,'sawtooth',.09);tone(160,.07,'triangle',.04);break;case 'alert':tone(440,.2,'triangle',.04);break;default:tone(370,.11,'sine',.04)}}};
setInterval(()=>{if(document.hidden)return;const notes=mood==='danger'?[110,116.5,146.8,130.8]:mood==='home'?[130.8,164.8,196,164.8]:[110,130.8,164.8,146.8];const f=notes[beat++%4];tone(f,1.8,'sine',.024);if(beat%2===0)tone(f*2,.6,'triangle',.01)},1000);
})();
